window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-inbox-tickets.html"]="<!-- Settings: Ticket Configuration -->\n<style>\n.tk-row{display:flex;justify-content:space-between;align-items:center;padding:10px 14px;border-bottom:1px solid var(--border);font-size:13px}\n.tk-row:last-child{border:none}\n.tk-cat{display:inline-flex;align-items:center;gap:6px;padding:4px 12px;border-radius:16px;font-size:12px;font-weight:600;background:var(--bg);border:1px solid var(--border)}\n.tk-cat .x{cursor:pointer;font-size:13px;color:var(--muted);font-weight:700}.tk-cat .x:hover{color:var(--danger)}\n.st-form label{display:block;font-size:13px;font-weight:500;margin-bottom:14px}\n.st-form label input,.st-form label select{display:block;width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:8px;margin-top:4px;font-size:14px;background:var(--bg)}\n.st-form label input:focus,.st-form label select:focus{outline:2px solid var(--accent);outline-offset:-1px}\n.tk-cat-bar{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\">\n    <div class=\"sn-title\">Organisasi</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-general')\">Umum</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-members')\">Anggota</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-roles')\">Role & Izin</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-tags')\">Tag</div>\n    <div class=\"sn-item\" onclick=\"go('settings/organization-shift-hours')\">Jam Shift</div>\n    <div class=\"sn-title\">Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-assignments')\">Assignment</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-team-inbox')\">Tim Inbox</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-sla')\">SLA</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-csat')\">CSAT</div>\n    <div class=\"sn-item\" onclick=\"go('settings/inbox-macros')\">Makro</div>\n    <div class=\"sn-item active\" onclick=\"go('settings/inbox-tickets')\">Tiket</div>\n    <div class=\"sn-title\">Channel</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-api')\">WhatsApp API</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-whatsapp-web')\">WhatsApp Web</div>\n    <div class=\"sn-item\" onclick=\"go('settings/channels-widget')\">Widget</div>\n    <div class=\"sn-title\">Billing</div>\n    <div class=\"sn-item\" onclick=\"go('settings/billing-cost')\">Kontrol Biaya</div>\n    <div class=\"sn-title\">Developer</div>\n    <div class=\"sn-item\" onclick=\"go('settings/developer-webhook')\">Webhook</div>\n  </aside>\n\n  <div class=\"settings-body\">\n    <h2 style=\"margin-bottom:4px\">Pengaturan Tiket</h2>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:20px\">Konfigurasi kategori dan prioritas default untuk tiket.</p>\n\n    <!-- Kategori -->\n    <div class=\"card\" style=\"padding:16px;margin-bottom:20px;max-width:520px\">\n      <h3 style=\"margin-bottom:12px\">Kategori Tiket</h3>\n      <div class=\"tk-cat-bar\" id=\"tkCatBar\"></div>\n      <div style=\"display:flex;gap:8px\">\n        <input id=\"tkNewCat\" placeholder=\"Tambah kategori…\" style=\"flex:1;padding:8px 12px;border:1px solid var(--border);border-radius:8px;font-size:13px;background:var(--bg)\">\n        <button class=\"btn primary\" onclick=\"addTkCat()\">Tambah</button>\n      </div>\n    </div>\n\n    <!-- Config Form -->\n    <div class=\"card st-form\" style=\"padding:16px;max-width:520px\">\n      <h3 style=\"margin-bottom:12px\">Konfigurasi Default</h3>\n      <label>Prioritas Default\n        <select id=\"tkDefaultPriority\">\n          <option value=\"low\">Rendah</option>\n          <option value=\"medium\">Sedang</option>\n          <option value=\"high\">Tinggi</option>\n        </select>\n      </label>\n      <label>Auto-assign Tiket\n        <select id=\"tkAutoAssign\">\n          <option value=\"true\">Ya</option>\n          <option value=\"false\">Tidak</option>\n        </select>\n      </label>\n      <label>SLA Penyelesaian (jam)\n        <input type=\"number\" id=\"tkSlaHours\" min=\"1\" placeholder=\"24\">\n      </label>\n      <div style=\"display:flex;justify-content:flex-end;margin-top:4px\">\n        <button class=\"btn primary\" onclick=\"saveTkConfig()\">Simpan</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n// ponytail: store ticket config in DB.settings.ticketConfig, create if missing\nif(!DB.settings.ticketConfig){\n  DB.settings.ticketConfig={\n    categories:['Order','Refund','Pengiriman','Teknis','Umum'],\n    defaultPriority:'medium',\n    autoAssign:true,\n    slaHours:24\n  };\n  saveStore();\n}\n\nvar cfg=DB.settings.ticketConfig;\n\nfunction renderCats(){\n  document.getElementById('tkCatBar').innerHTML=(cfg.categories||[]).map((c,i)=>\n    '<span class=\"tk-cat\">'+c+' <span class=\"x\" onclick=\"removeCat('+i+')\">×</span></span>'\n  ).join('');\n}\n\nfunction addTkCat(){\n  const inp=document.getElementById('tkNewCat');\n  const v=inp.value.trim();\n  if(!v)return;\n  if(cfg.categories.includes(v)){showToast('Kategori sudah ada');return}\n  cfg.categories.push(v);\n  saveStore();inp.value='';renderCats();\n}\n\nfunction removeCat(i){\n  cfg.categories.splice(i,1);\n  saveStore();renderCats();\n}\n\nfunction saveTkConfig(){\n  cfg.defaultPriority=document.getElementById('tkDefaultPriority').value;\n  cfg.autoAssign=document.getElementById('tkAutoAssign').value==='true';\n  cfg.slaHours=parseInt(document.getElementById('tkSlaHours').value)||24;\n  saveStore();\n  showToast('Pengaturan tiket berhasil disimpan');\n}\n\n// Init form values\ndocument.getElementById('tkDefaultPriority').value=cfg.defaultPriority;\ndocument.getElementById('tkAutoAssign').value=String(cfg.autoAssign);\ndocument.getElementById('tkSlaHours').value=cfg.slaHours;\nrenderCats();\n</script>\n";
